const cost=i=>{const h=hrs();if(i.t)return(i.t.h4!=null&&h<=5)?i.t.h4:tier(i,Math.max(1,Math.ceil(h/24)));const d=Math.floor(h/24),r=h-d*24;return i.p*d+Math.min(rate(i)*r,i.p)};
