function status(p){const l=bks(p),n=Date.now();let t=n,busy=false;const f=()=>l.find(b=>b.s<=t&&b.e>t);for(let c=f();c;c=f()){busy=true;t=c.e}
 return busy?{busy,free:t}:{busy,next:(l.find(b=>b.s>n)||{}).s}}
