function setPkg(k){readDur();S.pkg=k;S.wait=false;if(k!='more')applyPkg();else if(S.from){S.to=S.from.slice(0,10)+'T18:00';if(+new Date(S.to)<=+new Date(S.from))S.to=loc(+new Date(S.from)+288e5);S.wait=true}refreshDates()}
