function sumTxt(){return hrs()?'ระยะเวลาเช่า '+durTxt(hrs())+' · ราคารวม ฿'+sub().toLocaleString():(S.from&&S.to?'เวลาคืนต้องหลังเวลารับ':'เลือกวัน-เวลารับและคืน')}
const P2=n=>String(n).padStart(2,'0');
function dtField(id,v){const d=v?v.slice(0,10):'',h=v?v.slice(11,13):'',m=v?v.slice(14,16):'',min=loc(Date.now()).slice(0,10);
 let ho='<option value="">--</option>',mo='<option value="">--</option>';
 for(let i=0;i<24;i++)ho+=`<option value="${P2(i)}"${P2(i)==h?' selected':''}>${P2(i)}</option>`;
 const ms=[];for(let i=0;i<60;i+=5)ms.push(P2(i));if(m&&ms.indexOf(m)<0){ms.push(m);ms.sort()}
 ms.forEach(x=>mo+=`<option value="${x}"${x==m?' selected':''}>${x}</option>`);
 return `<input type="hidden" id="${id}" value="${v||''}"><div class="dtf"><input type="date" id="${id}_d" value="${d}" min="${min}" onchange="tchg('${id}')"><div class="tm"><select id="${id}_h" onchange="tchg('${id}')" aria-label="ชั่วโมง">${ho}</select><b>:</b><select id="${id}_m" onchange="tchg('${id}')" aria-label="นาที">${mo}</select><span class="mu">น.</span></div></div>`}
function setParts(id,v){const d=$(id+'_d'),h=$(id+'_h'),m=$(id+'_m');if(!d)return;const mm=v?v.slice(14,16):'';
 if(mm&&![...m.options].some(o=>o.value==mm))m.add(new Option(mm,mm));
 d.value=v?v.slice(0,10):'';h.value=v?v.slice(11,13):'';m.value=mm;$(id).value=v||''}
function refreshDates(){if(S.step!==1)return;setParts('st',S.from);setParts('en',S.to);const s=$('dsum');if(s)s.textContent=sumTxt();
 const pw=$('pkgw');if(pw)pw.innerHTML=pkgHtml();document.querySelectorAll('.calw').forEach(el=>{el.outerHTML=calHtml(el.dataset.p)});setBar()}
function tchg(id){const d=$(id+'_d').value;let h=$(id+'_h').value,m=$(id+'_m').value,v='';
 if(d){h=h||(id=='st'?'10':'18');m=m||'00';v=d+'T'+h+':'+m}
 $(id).value=v;readDur();S.wait=false;
 if(id=='st'&&S.pkg!='more'&&S.from){applyPkg();return refreshDates()}
 if(id=='en'&&S.pkg!='more'){S.pkg='more'}
 if(id=='st'&&S.from&&(!S.to||+new Date(S.to)<=+new Date(S.from)))S.to=loc(+new Date(S.from)+288e5);
 refreshDates()}

function pickItem(k,id){readDur();const a=S.sel[k]||(S.sel[k]=[]),n=a.findIndex(x=>x.id==id);n<0?a.push(CAT[k].items.find(x=>x.id==id)):a.splice(n,1);keep(render)}
function next1(){readDur();if(S.cats.some(k=>!(S.sel[k]||[]).length))return alert('กรุณาเลือกสินค้าให้ครบทุกประเภท');const[a,b]=range();if(!a||!b||b<=a)return alert('กรุณาเลือกวัน-เวลารับ และวัน-เวลาคืน (เวลาคืนต้องหลังเวลารับ)');if(a<Date.now()-3e5)return alert('เวลารับต้องไม่เป็นเวลาที่ผ่านมาแล้ว');if(hrs()>720)return alert('เช่าได้ไม่เกิน 30 วัน');const bad=picked().find(i=>bks(i.id).some(x=>x.s<b&&x.e>a));if(bad)return alert(bad.n+' ไม่ว่างในช่วงเวลาที่เลือก กรุณาดูปฏิทินแล้วเลือกใหม่');go(2)}
function tgl(){const sp=SHIP[$('f_del').value],t=sp.t;$('shiph').textContent=sp.h||'';$('addrw').style.display=t=='pickup'?'none':'';$('addrl').textContent=t=='name'?'ชื่อหอ/บ้าน *':'ที่อยู่จัดส่ง *';$('bw').style.display=$('d_bday').checked?'':'none';$('dpw').style.display=DISC.some(d=>$('d_'+d.k).checked)?'':'none'}
function zoom(src){const d=document.createElement('div');d.className='lb';d.onclick=()=>d.remove();d.innerHTML='<img src="'+src+'">';document.body.appendChild(d)}
function compress(file){return new Promise(r=>{const f=new FileReader();f.onload=()=>{const i=new Image();i.onerror=()=>r(f.result);i.onload=()=>{let m=2400,q=.93,d;const c=document.createElement('canvas'),x=c.getContext('2d');do{const k=Math.min(1,m/Math.max(i.width,i.height));c.width=Math.round(i.width*k);c.height=Math.round(i.height*k);x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(i,0,0,c.width,c.height);d=c.toDataURL('image/jpeg',q);q-=.04;m*=.92}while(d.length>2000000&&q>.5);r(d)};i.src=f.result};f.readAsDataURL(file)})}
async function pick(el,key){if(!el.files[0])return;const d=await compress(el.files[0]);if(key=='slip'){S.pay.slip=d;const p=$('slp');p.src=d;p.style.display='block'}else{S.cust[key]=d;let p=el.nextElementSibling;if(!p||p.tagName!='IMG'){p=document.createElement('img');p.className='th';p.onclick=()=>zoom(p.src);el.after(p)}p.src=d}}
function next2(){for(const k of['name','phone','addr'])S.cust[k]=$('f_'+k).value.trim();S.cust.deliver=$('f_del').value;DISC.forEach(d=>S.disc[d.k]=$('d_'+d.k).checked);S.cust.birth=$('f_birth').value;
 if(!S.cust.name||!S.cust.phone)return alert('กรุณากรอกชื่อและเบอร์โทร');if(!S.cust.ig)return alert('กรุณาแนบรูปหน้าโปรไฟล์ Instagram (แอคจริงเท่านั้น)');if(!S.cust.fb)return alert('กรุณาแนบรูปหน้าโปรไฟล์ Facebook (แอคจริงเท่านั้น)');{const t=SHIP[S.cust.deliver].t;if(t!='pickup'&&!S.cust.addr)return alert(t=='name'?'กรุณาแจ้งชื่อหอ/บ้าน':'กรุณากรอกที่อยู่จัดส่ง');}if(!S.cust.idimg)return alert('กรุณาแนบรูปบัตรประชาชน');
 if(DISC.some(d=>S.disc[d.k])){if(!S.cust.discimg)return alert('กรุณาแนบรูปหลักฐานส่วนลด')}else S.cust.discimg='';
 if(S.disc.bday&&(!S.cust.birth||S.cust.birth.slice(5,10)!=S.from.slice(5,10))){return alert('สิทธิ์วันเกิดใช้ได้เมื่อวันเกิดตรงกับวันที่รับสินค้า กรุณาตรวจสอบหรือยกเลิกสิทธิ์นี้')}
 if(!S.disc.bday)S.cust.birth='';if(SHIP[S.cust.deliver].t=='pickup')S.cust.addr='';toPay()}
const API='https://script.google.com/macros/s/AKfycbwwJauP5UbTvpi56-SvsLQVCzieR_lGdvhbbdzt3kBVqJTmDChGqLX5nIx_8bo-7j4uuQ/exec';
async function post(b){try{const r=await fetch(API,{method:'POST',body:JSON.stringify(b)});return await r.json()}catch(e){console.warn(e);return{ok:false,error:'network'}}}
async function toPay(){await loadBK();const[a,b]=range();const bad=picked().find(i=>bks(i.id).some(x=>x.s<b&&x.e>a));if(bad){alert(bad.n+' ไม่ว่างในช่วงเวลาที่เลือก กรุณาเลือกใหม่');return go(1)}go(3)}
async function submitPay(){
 if(!S.pay.slip)return alert('กรุณาแนบสลิปโอนเงิน');
 if(window._busy)return;window._busy=true;const btn=$('payBtn');if(btn){btn.disabled=true;btn.textContent='กำลังส่ง...'}
 try{
  if(!S.order){
   await loadBK();const[r0,r1]=range();const bad=picked().find(i=>bks(i.id).some(b=>b.s<r1&&b.e>r0));
   if(bad){alert(bad.n+' ไม่ว่างในช่วงเวลาที่เลือก หากโอนเงินแล้วกรุณาติดต่อร้าน');return go(1)}
   const id='o'+Date.now()+Math.random().toString(36).slice(2,6);
   const o={id,no:String(Date.now()).slice(-6),type:S.cats.map(k=>CAT[k].n).join(' + '),items:picked().map(i=>({n:i.n,c:cost(i)})),from:S.from,to:S.to,hrs:hrs(),sub:sub(),disc:discList().map(d=>({n:d.n,a:d.a})),total:total(),ship:{n:SHIP[S.cust.deliver].n,fee:shipFee()},cust:{...S.cust},created:new Date().toISOString()};
   const r=await post({action:'order',order:o,bk:picked().map(i=>({pid:i.id,s:r0,e:r1}))});
   if(!r.ok){if(r.error=='conflict'){alert('สินค้าเพิ่งถูกจองในช่วงเวลานี้ หากโอนเงินแล้วกรุณาติดต่อร้าน');return go(1)}return alert('ส่งออเดอร์ไม่สำเร็จ กรุณาลองใหม่อีกครั้ง')}
   S.order=o}
  const r2=await post({action:'pay',id:S.order.id,slip:S.pay.slip});
  if(!r2.ok)return alert('แจ้งชำระเงินไม่สำเร็จ กรุณากดอีกครั้ง');
  go(4)
 }finally{window._busy=false;const b=$('payBtn');if(b){b.disabled=false;b.textContent='แจ้งชำระเงินแล้ว'}}
}
function copyAcc(){try{navigator.clipboard.writeText('1768315589').then(()=>alert('คัดลอกเลขบัญชีแล้ว'))}catch(e){alert('เลขบัญชี 176-8-31558-9')}}
function burst(){for(let i=0;i<22;i++){const e=document.createElement('span');e.className='bt';e.textContent=['✦','✧','♡','💖','✨'][i%5];e.style.cssText=`left:${Math.random()*100}vw;animation-delay:${Math.random()*.6}s;font-size:${14+Math.random()*16}px`;document.body.appendChild(e);setTimeout(()=>e.remove(),3400)}}
render();loadBK().then(()=>{if(S.step===1){readDur();render()}});setInterval(async()=>{await loadBK();if(S.step===1){readDur();render()}},90000);
